'use strict';
NAV.splice(9,0,['connections','People & links']);iconPaths.connections=iconPaths.user;
Object.assign(entityPage,{people:'connections',business_people:'connections',business_links:'connections'});
Object.assign(configs,{
 people:{title:'Person',fields:[field('name','Name','text',true),field('email','Sign-in email','email'),field('phone','Phone'),select('status','Access status',['Active','Paused'],true),field('profile_url','Website / profile','url'),field('notes','Private owner notes','textarea')]},
 business_people:{title:'Business membership',fields:[B,refField('person_id','Person','people',true),field('role','Role in this business','text',true),select('status','Membership status',['Active','Paused'],true),field('notes','Private scope / agreement','textarea')]},
 business_links:{title:'Business link',fields:[field('title','Link name','text',true),B,C,refField('person_id','Related person','people'),select('kind','Link type',['Website','Social profile','Assets','Admin','Partner','Other']),field('url','Link URL','url',true),field('notes','Link notes','textarea')]}
});
for(const type of ['tasks'])configs[type].fields.push(refField('assignee_id','Assign to business member','people'));
configs.tasks.fields.push(refField('business_link_id','Related business link','business_links'),field('progress_note','Collaborator progress note','textarea'));
function connectionsPage(){const memberships=all('business_people'),people=store.people.filter(p=>!scope||memberships.some(m=>m.person_id===p.id)),links=all('business_links');return heading('The people behind your businesses.','Add a person, link them to a business, then assign their work. Each member sees only their own assigned tasks.',`${addbtn('people','Add person')}${newOperation('business_people','Link person to business',scope)}${newOperation('business_links','Add link',scope)}`)+`<div class="stats">${stat('People',people.length,'Your collaborators','user',true)}${stat('Active memberships',memberships.filter(m=>m.status==='Active').length,'Business access','businesses')}${stat('Assigned open tasks',all('tasks').filter(t=>t.assignee_id&&t.status!=='Done').length,'Work moving with your team','tasks')}</div><div class="info">Invite links last 72 hours and can be used once. Members set their own password. Pausing a person or their membership removes their access to that business.</div><div class="connection-grid">${people.map(p=>{const member=memberships.filter(m=>m.person_id===p.id),assigned=all('tasks').filter(t=>t.assignee_id===p.id&&t.status!=='Done');return `<section class="card connection-person"><div class="ops-card-top">${badge(p.status)}${editbtn('people',p.id)}</div><h2>${esc(p.name)}</h2><p class="muted">${esc(p.email||'Add an email to invite')}${p.phone?' · '+esc(p.phone):''}</p><div class="row-list">${member.map(m=>`<div class="list-row"><div class="grow"><strong>${esc(bname(m.business_id))}</strong><p>${esc(m.role)} · ${esc(m.status)}</p></div>${editbtn('business_people',m.id)}${m.status==='Active'?btn('Assign task','assign-person',`data-person="${esc(p.id)}" data-business="${esc(m.business_id)}"`,'secondary compact'):''}</div>`).join('')||'<p class="notice">Link this person to a business first.</p>'}</div><p class="section-gap">${assigned.length} open assigned tasks</p><div class="actions">${btn('Add business','link-person',`data-person="${esc(p.id)}"`,'secondary compact')}${p.email&&member.some(m=>m.status==='Active')?btn('Create invite / reset access','invite-person',`data-person="${esc(p.id)}"`,'secondary compact'):''}${safeLink(p.profile_url,'Open profile','btn secondary compact')}</div></section>`;}).join('')||empty('Work with the right people','Add your first collaborator and choose their business.')}</div><div class="section-gap">${card('Business links',opRows('business_links',links,[['Link',l=>safeLink(l.url,l.title)],['Business',l=>esc(bname(l.business_id))],['Type',l=>esc(l.kind)],['Person',l=>esc(store.people.find(p=>p.id===l.person_id)?.name||'—')]]),newOperation('business_links','Add link',scope))}</div>`;}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(!['business-connections','assign-person','link-person','invite-person','open-publisher'].includes(action))return;event.preventDefault();try{
 if(action==='business-connections'){scope=el.dataset.business;go('connections');}
 if(action==='assign-person')openEditor('tasks','',{business_id:el.dataset.business,assignee_id:el.dataset.person,origin:'GROW',status:'Open',priority:'Medium',recurrence:'None'});
 if(action==='link-person')openEditor('business_people','',{business_id:scope,person_id:el.dataset.person,status:'Active'});
 if(action==='invite-person'){el.disabled=true;const invite=await api('people/'+el.dataset.person+'/invite','POST',{});openDialog(`${dialogHead('Invite '+(store.people.find(p=>p.id===el.dataset.person)?.name||'member'),'Share this link with the person directly.')}<div class="dialog-body"><p>This private invitation lets them choose their own password. It expires ${esc(new Date(invite.expires).toLocaleString())} and works once.</p><input class="invite-copy" value="${esc(invite.url)}" readonly aria-label="Invitation link" id="invite-url"><button class="btn secondary" data-action="copy-invite">Copy invitation</button><p class="notice">Creating a new invitation replaces any previous unused invitation. Existing access changes only after they activate it.</p></div><div class="dialog-actions">${btn('Close','close')}</div>`);}
 if(action==='open-publisher')await openPublisher(el.dataset.id);
 }catch(error){toast(error.message,true);}finally{el.disabled=false;}});
document.addEventListener('click',async event=>{if(event.target.closest('[data-action="copy-invite"]')){try{await navigator.clipboard.writeText(document.querySelector('#invite-url').value);toast('Invitation copied.');}catch{document.querySelector('#invite-url').select();toast('Select and copy this invitation link.');}}});
let publisherContentId='',publisherAccounts=[];
function publisherFiles(c){return JSON.parse(c.publisher_media||'[]').map(m=>`<div class="list-row"><div class="grow"><strong>${esc(m.filename)}</strong><p>${(m.bytes/1024/1024).toFixed(2)} MB · ${esc(m.contentType)}</p></div>${['Idea','Draft','Changes requested'].includes(c.status)?btn('Detach','publisher-detach',`data-media="${esc(m.id)}"`,'secondary compact'):''}</div>`).join('')||'<p class="notice">No uploaded attachments. Asset links remain reference links; upload the actual file here to include it in your Social post.</p>';}
async function openPublisher(id){publisherContentId=id;const c=found('content',id);if(!c)return;let issue='';try{publisherAccounts=(await api('social/accounts')).accounts;}catch(error){publisherAccounts=[];issue=error.message;}
const platform={Facebook:'facebook',Instagram:'instagram',LinkedIn:'linkedin',YouTube:'youtube','YouTube Shorts':'youtube',X:'x',TikTok:'tiktok'}[c.channel],saved=JSON.parse(c.publisher_account_ids||'[]'),preferred=client(c.client_id)?.publisher_account_id||business(c.business_id)?.publisher_account_id,accounts=publisherAccounts.filter(a=>a.platform===platform),approved=['Approved','Scheduled'].includes(c.status),locked=['publishing','published','uncertain'].includes(c.publisher_state),uploadable=['Idea','Draft','Changes requested'].includes(c.status)&&!locked;
openDialog(`${dialogHead('Send to Social',c.title+' · '+c.channel)}<div class="dialog-body"><div class="info">${platform==='facebook'?'Choose the Facebook Pages for this business or client. Send an approved draft, then publish it when ready.':'Send an approved draft to your Social workspace, then open it to review. This network currently supports draft handoff.'}</div>${issue?`<p class="form-error">${esc(issue)}</p>`:''}<p>${badge(c.status)} ${sampleTag(c)} ${c.publisher_state?badge('Social: '+c.publisher_state):''}</p>${c.publisher_error?`<p class="form-error">${esc(c.publisher_error)}</p>`:''}<p class="copy">${esc(c.copy||'(Media only)')}</p><h3>Attachments</h3><div class="publisher-files">${publisherFiles(c)}</div>${uploadable?'<label class="btn secondary">Upload photos / video<input id="publisher-upload" type="file" accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,video/webm,video/quicktime" multiple hidden></label>':'<p class="notice">Attachments can be changed while the content is a draft. Review and approve it after uploading.</p>'}<h3 class="section-gap">${platform==='facebook'?'Facebook Pages':'Destinations'}</h3><form id="publisher-form">${accounts.length?'<input id="publisher-account-search" class="invite-copy" placeholder="Find a Page or profile by name" aria-label="Find Social destination">':''}<div class="publisher-destinations">${accounts.map(a=>`<label class="publisher-account publisher-destination" data-label="${esc(a.label.toLowerCase())}"><input name="accountIds" type="checkbox" value="${esc(a.id)}" ${(saved.length?saved.includes(a.id):a.id===preferred)?'checked':''} ${locked?'disabled':''}><span>${esc(a.label)} · ${esc(a.connectionStatus)}</span></label>`).join('')||'<p class="notice">No connected destination for this network. You can send a draft, then connect your account in Social.</p>'}</div>${accounts.length?`<label class="publisher-account"><input name="rememberDestination" type="checkbox"><span>Use the selected destination as ${c.client_id?'this client’s':'this business’s'} default (choose one).</span></label>`:''}${approved&&!locked?'<button class="btn primary" type="submit">Send approved draft to Social</button>':'<p class="notice">'+(locked?'Check the publishing result below.':'Submit this content for review and approve it before sending.')+'</p>'}</form>${c.publisher_post_id?`<div class="actions section-gap">${safeLink('https://social.iamjubayer.com/?growPost='+c.publisher_post_id,'Open this draft in Social','btn secondary')}${btn('Check publishing result','publisher-status')}${approved&&!c.demo&&platform==='facebook'&&saved.length&&c.publisher_state!=='published'?btn('Publish to selected Pages now','publisher-confirm','','primary'):''}</div>`:`<div class="section-gap">${safeLink('https://social.iamjubayer.com/','Open Social','btn secondary')}</div>`}<p class="notice">${c.demo?'Sample content can be sent as a draft only. Create your own record before live publishing. ':''}Calendar dates are planning reminders. Publishing sends immediately only when you choose Publish now. GROW marks the content Published after Social reports success.</p></div><div class="dialog-actions">${btn('Close','close')}</div>`);
}
document.addEventListener('submit',async event=>{if(event.target.id!=='publisher-form')return;event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;try{const accountIds=new FormData(event.target).getAll('accountIds');await api('content/'+publisherContentId+'/social/draft','POST',{accountIds});if(new FormData(event.target).has('rememberDestination')&&accountIds.length===1){const c=found('content',publisherContentId);await api((c.client_id?'clients/'+c.client_id:'businesses/'+c.business_id),'PATCH',{publisher_account_id:accountIds[0]});}await refresh();render();await openPublisher(publisherContentId);toast('Draft and uploaded media sent to Social.');}catch(error){toast(error.message,true);}finally{button.disabled=false;}});
document.addEventListener('change',async event=>{if(event.target.id!=='publisher-upload')return;const files=Array.from(event.target.files),id=publisherContentId;event.target.disabled=true;try{for(const file of files){if(file.size>50*1024*1024)throw new Error('Files are limited to 50 MB.');const res=await fetch('/api/content/'+id+'/social/upload',{method:'POST',headers:{'X-Grow-Token':csrf,'X-File-Size':String(file.size),'X-File-Name':encodeURIComponent(file.name),'Content-Type':file.type||'application/octet-stream'},body:file}),value=await res.json();if(!res.ok)throw new Error(value.error||'Upload failed.');}toast('Attachments uploaded. Review and approve the draft before sending.');}catch(error){toast(error.message,true);}finally{await refresh();render();await openPublisher(id);}});
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el||!['publisher-detach','publisher-status','publisher-confirm','publisher-publish'].includes(el.dataset.action))return;const action=el.dataset.action,id=publisherContentId;el.disabled=true;try{
 if(action==='publisher-confirm'){const c=found('content',id),selected=JSON.parse(c.publisher_account_ids||'[]');const labels=selected.map(s=>publisherAccounts.find(a=>a.id===s)?.label||s);openDialog(`${dialogHead('Publish now?',c.title)}<div class="dialog-body"><p>This sends the approved content immediately to these selected Facebook Pages:</p><ul>${labels.map(l=>'<li>'+esc(l)+'</li>').join('')}</ul><p class="copy">${esc(c.copy)}</p><p>${JSON.parse(c.publisher_media||'[]').length} uploaded attachments</p></div><div class="dialog-actions">${btn('Back','open-publisher',`data-id="${esc(id)}"`)}${btn('Publish now','publisher-publish','','primary')}</div>`);return;}
 await api('content/'+id+'/social/'+(action==='publisher-detach'?'detach':action==='publisher-status'?'status':'publish'),'POST',action==='publisher-detach'?{mediaId:el.dataset.media}:{});await refresh();render();await openPublisher(id);toast(action==='publisher-publish'?'Publishing requested. Check the result to see when it completes.':'Social connection updated.');
 }catch(error){toast(error.message,true);await refresh();render();await openPublisher(id);}finally{el.disabled=false;}});
const baseEditor=openEditor;
openEditor=function(entity,id='',defaults={}){
 baseEditor(entity,id,defaults);
 if(id&&['content','projects','website_work','productions'].includes(entity)){
  const actions=document.querySelector('#editor .dialog-actions');if(actions)actions.insertAdjacentHTML('afterbegin',btn('Assign work as a task','assign-linked-work',`data-entity="${esc(entity)}" data-id="${esc(id)}"`));
 }
};
document.addEventListener('click',event=>{const el=event.target.closest('[data-action="assign-linked-work"]');if(!el)return;const entity=el.dataset.entity,record=found(entity,el.dataset.id),linked={content:'content_id',projects:'project_id',productions:'production_id'}[entity];openEditor('tasks','',{title:record.title,business_id:record.business_id,client_id:record.client_id||'',...(linked?{[linked]:record.id}:{}),url:entity==='website_work'?record.url:'',due:record.due||record.date||'',notes:record.brief||record.notes||'',status:'Open',priority:'Medium',origin:'GROW',recurrence:'None'});});
document.addEventListener('input',event=>{if(event.target.id==='publisher-account-search')for(const label of document.querySelectorAll('.publisher-destination'))label.hidden=!label.dataset.label.includes(event.target.value.trim().toLowerCase());});
boot();
